export async function readAuthResponse(response){const contentType=response.headers.get('content-type')||'';const text=await response.text();if(!contentType.includes('application/json'))throw Error('The sign-in service is not available. Refresh this page; if it continues, restart the updated Campus server.');let result;try{result=JSON.parse(text)}catch{throw Error('The sign-in service returned an invalid response. Please refresh and try again.')}if(!result||typeof result!=='object')throw Error('The sign-in service returned an invalid response. Please refresh and try again.');return result}
